/* @lc app=leetcode id=3806 lang=kotlin */ class Solution { fun need(a: Long, x: Long): Long = if (a and x == x) 0L else (0..40).first { p -> (a shr p and 1L) == 0L && ((a shr (p + 1)) and (x shr (p + 1))) == (x shr (p + 1)) }.let { p -> (((a shr (p + 1)) shl (p + 1)) or (1L shl p) or (x and ((1L shl p) - 1))) - a } fun maximumAND(nums: IntArray, k: Int, m: Int): Int = (31 downTo 0).fold(0L) { acc, b -> (acc or (1L shl b)).let { cand -> if (nums.map { need(it.toLong(), cand) }.sorted().take(m).sum() <= k) cand else acc } }.toInt() }